// The town hub: the map maps/town.tmj (generated by tiled/make-town-map.js) in the test level's scene (TestMap), plus what only a town has.
//   - Nothing hostile, nothing to farm (no gold from sheep or bushes); NPCs to talk to (src/npc.js) whose dialogs lead into the shops and the trainer.
//   - The hero is made from the save (save.js runStart): permanent stats, loadout, meat, whetstone tier, Second Wind, the old or the new Pawn.
//   - A `sail` rect (between the two Towers of the main gate): walking into it starts a run, through the Sail scene to island 1 (the test level for now).
//   - After a fall on an island the hero washes up on the beach (init data { washup: true }): a Water Splash, then he rises.
// init data: { washup, at (a spawn name), pos ([x, y] to stand at: after a rebuild) }.
class Town extends TestMap {
  constructor() { super('Town') }
  get mapName() { return 'town' }
  init(d) { super.init(d); this.town = true; if (this.run.washup) this.run.at = 'beach' }
  // a run as the save sets it up. ?hero=new tries the new Pawn without buying it.
  startHero() {
    const st = runStart(SAVE);
    if (new URLSearchParams(location.search).get('hero') === 'new') st.form = 'new';
    return st;
  }
  build(m, name) {
    super.build(m, name);
    SFX.music(this, 'town');
    this.sailRect = m.objects.find(o => o.cls === 'sail');
    const tex = this.textures.get('fence');                           // the yards' fences: one rect per cell, the piece named in `p` (data.js YARD), from the Camp's sheet
    for (const o of m.objects) if (o.cls === 'fence' && YARD[o.props.p]) {
      const [r, c, bands] = YARD[o.props.p], name = `${r},${c}`;
      if (!tex.has(name)) tex.add(name, 0, c * T, r * T, T, T);
      this.add.image(o.x, o.y, 'fence', name).setOrigin(0).setDepth(o.y + Math.max(...bands.map(b => b[3])));
      for (const b of bands) this.place({ x0: o.x + b[0], y0: o.y + b[1], x1: o.x + b[2], y1: o.y + b[3], high: false, gone: false });
    }
    // buying changes the hero: the new Pawn is a different sprite (rebuild, standing where he stood), the rest is a fresh load of the stats
    this.on(this.events, 'resume', () => {
      const h = this.hero;
      if (h.form !== this.startHero().form) return this.scene.restart({ pos: [h.x, h.y] });
      h.load({ ...this.startHero(), flip: h.sprite.flipX });
    });
    if (this.run.washup) this.washUp();
  }
  // from the sea onto the beach: the splash, then the death animation played backwards (he gets up). Input waits.
  washUp() {
    const h = this.hero, cam = this.cameras.main, x = h.x, y = h.y, d = this.depthOf(h);
    h.sprite.setVisible(false); this.leaving = true;
    cam.fadeIn(900);
    const lie = this.add.sprite(x, y, 'odead').setOrigin(0.5, 0.72).setDepth(d).setFrame(6).setVisible(false);
    this.time.delayedCall(300, () => {
      const s = this.add.sprite(x, y + 4, 'water-splash').setDepth(d + 1).play('water-splash');
      SFX.play(this, 'splash');
      s.once('animationcomplete', () => s.destroy());
      lie.setVisible(true).anims.playReverse('odead-dead');
    });
    lie.once('animationcomplete', () => { lie.destroy(); h.sprite.setVisible(true); this.leaving = false });
  }
  onDead() { this.time.delayedCall(2200, () => this.scene.restart({ washup: true })) }   // only the H key can hurt him here
  update(time, dt) {
    super.update(time, dt);
    const h = this.hero;
    if (this.ready && !this.leaving && !h.dead && this.sailRect && feetHit(this.sailRect, h)) this.setSail();
  }
  // through the main gate: the sea takes him to island 1
  setSail() {
    this.leaving = true; SFX.play(this, 'sail'); SFX.stopMusic(this, 400);   // (under the 500 ms fade: the tween must end before this scene stops)
    const cam = this.cameras.main;
    cam.fadeOut(500);
    cam.once('camerafadeoutcomplete', () => this.scene.start('Sail', { island: 1, hero: this.startHero() }));
  }
}
